    elif sw==3:
        b=np.frombuffer(raw,dtype=np.uint8).reshape(-1,3); v=(b[:,0].astype(np.int32)|(b[:,1].astype(np.int32)<<8)|(b[:,2].astype(np.int32)<<16)); v=np.where(v>=1<<23,v-(1<<24),v); d=v/float(1<<23)
